import json
from collections import deque
def comps(I, bg=1, conn=8):
    H,W=len(I),len(I[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for i in range(H):
        for j in range(W):
            if I[i][j]==bg and not seen[i][j]:
                q=deque([(i,j)]); seen[i][j]=True; cells=[]
                while q:
                    a,b=q.popleft(); cells.append((a,b))
                    for di in (-1,0,1):
                        for dj in (-1,0,1):
                            x,y=a+di,b+dj
                            if 0<=x<H and 0<=y<W and not seen[x][y] and I[x][y]==bg:
                                seen[x][y]=True; q.append((x,y))
                out.append(cells)
    return out
