def seg(v,skip=True):
    pts=bycolor[v]
    if len(pts)<2: return set()
    res=set(); 
    for a,b in itertools.combinations(pts,2):
        r0,c0,r1,c1=a[0],a[1],b[0],b[1]
        dr,dc=r1-r0,c1-c0; steps=max(abs(dr),abs(dc))
        if steps==0 or (steps!=max(abs(dr),abs(dc))) : continue
        for t in range(1+(0 if not skip else 1)):  # endpoints excluded by default
            y,x=int(r0+t*dr/steps),int(c0+t*dc/steps)
            res.add((y//3,x//3))
    return res
