        dy=int(cy-a); dx=int(cx-b)
        if mode=='cent':
            moves=[]
            if dy!=0: moves.append((dy,0))
            if dx!=0: moves.append((0,dx))
            if abs(dy)==abs(dx) and dy and dx: moves.append(((dy if dy>0 else -dy),(dx if dx>0 else -dx)))
        elif mode=='diag':
            s=1 if (a<=cy and b<=cx) else -1
            moves=[(s,s)] if (a<cy or b<cx) else []
        elif mode=='down':
            moves=[(1,0)] if a<2 else []
        else: raise ValueError(mode)
        if not moves: continue
        cand=moves[0]
        na,nb=a+cand[0],b+cand[1]
        if 0<=na<3 and 0<=nb<3 and (na,nb) not in occ:
            res.append((na,nb))
        else:
            res.append((a,b))
    return set(res)
